spec.expr:
topk(
  10,
  sum by (namespace, container) (
    rate(
      {
        cluster="k3s-lab",
        namespace=~".+",
        container=~".+"
      }
        |~ "(?i)(error|exception|fatal|panic|failed|failure)"
      [$__auto]
    )
  )
)

sum by (priority) (
  rate(
    {
      cluster="k3s-lab",
      source="journal",
      priority=~".+"
    }[$__auto]
  )
)

